// Kwara Innovation Lab WhatsApp agent - intake, scope gates and customer context.
const CONFIG = {
  staffPhones: ['234XXXXXXXXXX'],   // human team WhatsApp numbers (digits only, with country code)
  staleAfterSeconds: 300,           // ignore very old redelivered messages
  maxMessagesPerHour: 40,           // per customer, protects AI spend
  humanPauseHours: 2,               // how long "/bot off" pauses the bot for a customer
};

const sd = $getWorkflowStaticData('global');   // persists only while the workflow is ACTIVE
sd.seen = sd.seen || [];
sd.paused = sd.paused || {};
sd.rate = sd.rate || {};

const body = $input.first().json;
const value = body.entry?.[0]?.changes?.[0]?.value ?? body;
const msg = value.messages?.[0];
if (!msg) return [];                            // delivery/read status updates carry no message

const digits = (s) => String(s || '').replace(/\D/g, '');
const from = digits(msg.from);
const now = Date.now();

// 1) Dedupe: Meta retries webhooks
if (sd.seen.includes(msg.id)) return [];
sd.seen.push(msg.id);
if (sd.seen.length > 200) sd.seen = sd.seen.slice(-200);

// 2) Stale backlog guard
if (msg.timestamp && (now / 1000 - Number(msg.timestamp)) > CONFIG.staleAfterSeconds) return [];

// 3) Staff messages are never answered by the bot. Staff can pause/resume it per customer:
//    "/bot off 2348012345678"  or  "/bot on 2348012345678"
if (CONFIG.staffPhones.includes(from)) {
  const m = (msg.text?.body || '').trim().match(/^\/bot\s+(on|off)\s+(\+?[\d\s-]+)$/i);
  if (m) {
    const target = digits(m[2]);
    if (m[1].toLowerCase() === 'off') sd.paused[target] = now + CONFIG.humanPauseHours * 3600 * 1000;
    else delete sd.paused[target];
  }
  return [];
}

// 4) Human takeover pause
if (sd.paused[from] && sd.paused[from] > now) return [];
if (sd.paused[from]) delete sd.paused[from];

// 5) Per-customer rate limit
const r = sd.rate[from];
if (!r || now - r.start > 3600 * 1000) sd.rate[from] = { start: now, count: 1 };
else if (++r.count > CONFIG.maxMessagesPerHour) return [];

// 6) Message text (attachments become a bracketed note the agent understands)
let text = '';
if (msg.type === 'text') text = msg.text?.body || '';
else if (msg.type === 'button') text = msg.button?.text || '';
else if (msg.type === 'interactive') text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
else text = `[The customer sent a ${msg.type || 'message'} with no text]`;
text = text.trim().slice(0, 1500);
if (!text) return [];

const ref = 'KIL-' + Array.from({ length: 5 }, () => 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random() * 32)]).join('');

return [{ json: {
  customer: from,
  name: (value.contacts?.[0]?.profile?.name || '').replace(/["\n\r]/g, ' ').slice(0, 40),
  text,
  messageId: msg.id,
  phoneNumberId: value.metadata?.phone_number_id,
  bookingRef: ref,
  staffPhone: CONFIG.staffPhones[0],
} }];

// Parse the agent's JSON, apply dedupe, and prepare the WhatsApp / Sheets payloads.
const n = $('Normalize').first().json;
const out = $input.first().json;
const raw = String(out.output ?? out.text ?? '');
const sd = $getWorkflowStaticData('global');
sd.dedupe = sd.dedupe || {};

const FALLBACK = "Sorry, I'm having a little trouble right now. Please reach our team: WhatsApp 0XXXXXXXXXX, call 0XXXXXXXXXX (9 AM - 4 PM) or email info@example.org.";
const clean = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

let data = null;
try {
  const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
  data = JSON.parse(raw.slice(start, end + 1));
} catch (e) { data = null; }

let reply = data && typeof data.reply === 'string' ? data.reply : '';
if (!reply) reply = FALLBACK;
reply = reply.replace(/\*\*/g, '*').replace(/^#+\s*/gm, '').trim().slice(0, 3500);

const now = Date.now();
const fresh = (key, ttlMs) => {
  if (sd.dedupe[key] && now - sd.dedupe[key] < ttlMs) return false;
  sd.dedupe[key] = now;
  for (const k of Object.keys(sd.dedupe)) if (now - sd.dedupe[k] > 3600 * 1000) delete sd.dedupe[k];
  return true;
};

const link = `${n.name || 'Customer'} - https://wa.me/${n.customer}`;
const result = {
  customer: n.customer, phoneNumberId: n.phoneNumberId, staffPhone: n.staffPhone,
  reply, isBooking: false, isEscalation: false, bookingMessage: '', escalationMessage: '',
  sheetRow: {},
};

// Booking
const b = data && data.booking && typeof data.booking === 'object' ? data.booking : null;
if (b && clean(b.full_name, 80) && clean(b.programme, 100) &&
    fresh(`b|${n.customer}|${clean(b.programme, 100).toLowerCase()}`, 15 * 60 * 1000)) {
  const row = {
    Reference: n.bookingRef,
    Date: $now.setZone('Africa/Lagos').toFormat('yyyy-MM-dd HH:mm'),
    'Customer WhatsApp': n.customer,
    'WhatsApp Name': n.name,
    'Full Name': clean(b.full_name, 80),
    Programme: clean(b.programme, 100),
    Category: clean(b.customer_type, 40),
    'Preferred Start': clean(b.preferred_start_month, 40),
    Payment: clean(b.payment_preference, 30) || 'Not decided',
    'Child Age': clean(b.child_age, 3),
    Notes: clean(b.notes, 300),
    Status: 'New',
  };
  result.isBooking = true;
  result.sheetRow = row;
  result.bookingMessage = [
    `\uD83D\uDCCC NEW BOOKING REQUEST ${row.Reference}`,
    `Name: ${row['Full Name']}`,
    `Programme: ${row.Programme}`,
    `Category: ${row.Category}`,
    `Preferred start: ${row['Preferred Start']}`,
    `Payment: ${row.Payment}`,
    row['Child Age'] ? `Child's age: ${row['Child Age']}` : '',
    row.Notes ? `Notes: ${row.Notes}` : '',
    `Customer: ${link}`,
  ].filter(Boolean).join('\n');
}

// Escalation
const e = data && data.escalate && typeof data.escalate === 'object' ? data.escalate : null;
if (e) {
  const reason = clean(e.reason, 30) || 'other';
  if (fresh(`e|${n.customer}|${reason}`, 30 * 60 * 1000)) {
    result.isEscalation = true;
    result.escalationMessage = `\u26A0\uFE0F ESCALATION (${reason})\nCustomer: ${link}\nSummary: ${clean(e.summary, 400)}`;
  }
}
return [{ json: result }];
